"""Fresh small problems: reason from supplied inputs, never recall stored model scores."""
import contextlib, io, re
CASES={
1:('pred=[1,0,1,V]\ny=[1,1,1,V]\nprint(sum(a==b for a,b in zip(pred,y)),len(y))','Count matching predictions. The output is correct-count then sample-count, not the number of classes.'),
2:('from sklearn.linear_model import LinearRegression\nm=LinearRegression().fit([[0],[1]],[1,V])\nprint(round(float(m.predict([[2]])[0]),2))','The fitted line passes through the two supplied points. Work out the slope, intercept and prediction; no frozen example score is needed.'),
3:('steps=["load","fit","predict"]\nprint(steps[:V])','A slice stops before its ending index and cannot return more entries than the list contains. Cell order and reproducibility require understanding what executed.'),
4:('import numpy as np\nx=np.arange(12).reshape(4,3)\nprint(x[:V,[0]].shape)','The row slice selects V rows and the list-valued column selection preserves one feature dimension.'),
5:('import pandas as pd\ndf=pd.DataFrame({"x":[1,None,V],"target":[0,1,0]})\nprint(df[["x"]].shape, int(df["x"].isna().sum()))','Double brackets preserve a DataFrame. There are three rows, one selected feature and one missing x entry.'),
6:('values=[1,1,2,V]\nprint(min(values),max(values),len(values))','Read range and sample size before interpreting a plot. An extreme value changes the maximum, not the number of samples.'),
7:('n=40\ntest=V*5\nvalidation=5\nprint(n-test-validation,test)','Subtract validation and test examples from the total to obtain training examples. Each role remains separate.'),
8:('from sklearn.preprocessing import StandardScaler\ns=StandardScaler().fit([[0],[2]])\nprint(s.transform([[V]]).round(1).tolist())','The training mean is 1 and population standard deviation is 1; transform subtracts 1 without refitting on the new input.'),
9:('fold_scores=[0.5,0.75,1.0]\nprint(len(fold_scores),round(sum(fold_scores)/len(fold_scores),2))\nprint("fits",V*len(fold_scores))','The average is 0.75. Each candidate needs one fresh fit per fold, so V candidates require V times three fits, before any refit.'),
10:('w=V\nb=1\nx=4\nprint(w*x+b)','A linear prediction is coefficient times input plus intercept. The coefficient is supplied, so this tests prediction rather than memorized fitted output.'),
11:('from sklearn.metrics import mean_absolute_error\ny=[0,2]\np=[V,2]\nprint(mean_absolute_error(y,p))','Absolute errors are V and zero; their average is V/2 in target units.'),
12:('classes=["cat","dog"]\np=[0.2,0.8]\nprint(classes[p.index(max(p))], sum(p))','Probability columns follow the supplied class order. The larger probability determines the label; the two probabilities sum to one.'),
13:('tp=V\nfp=1\nfn=2\nprint(round(tp/(tp+fp),3),round(tp/(tp+fn),3))','Precision is TP/(TP+FP); recall is TP/(TP+FN). Different denominators ask different questions.'),
14:('from sklearn.impute import SimpleImputer\ns=SimpleImputer(strategy="median").fit([[1],[V],[9]])\nprint(s.transform([[float("nan")]]).tolist())','The median of 1, V and 9 is V for these variants. The held-out missing entry uses the training replacement.'),
15:('from sklearn.preprocessing import OneHotEncoder\ne=OneHotEncoder(handle_unknown="ignore",sparse_output=False).fit([["A"],["B"]])\nprint(e.transform([["C"]]*V).shape)','Unknown categories keep the learned output width. V future rows and two learned indicators give a V by 2 table.'),
16:('from sklearn.preprocessing import PolynomialFeatures\np=PolynomialFeatures(degree=2,include_bias=False)\nprint(p.fit_transform([[1,V]]).shape)','Two input features produce x0, x1, x0 squared, their interaction and x1 squared: five columns.'),
17:('import pandas as pd\nx=pd.DataFrame({"x":[1]*V,"city":["A"]*V})\nprint(x[["city"]].shape, x.columns.tolist())','Selecting one named column keeps all V rows; the raw feature names remain x and city.'),
18:('import numpy as np\ny=V\nprint(round(float(np.expm1(np.log1p(y))),3))','log1p and expm1 reverse one another on this valid domain. Apply the inverse only once.'),
19:('weights=[V,-1]\nprint(sum(abs(w) for w in weights),sum(w*w for w in weights))','The first sum resembles an L1 penalty; the second a squared L2 penalty. They respond differently to coefficient magnitude.'),
20:('from collections import Counter\nneighbors=[0,1,1][:V]\nprint(Counter(neighbors).most_common(1)[0][0])','Count the labels among the supplied nearest neighbors. For the two-row tie this Counter demonstration keeps first occurrence; a real estimator tie policy must be read rather than assumed.'),
21:('votes=[0,1,1,1,0]\nprint(sum(votes),len(votes),sum(votes)>len(votes)/2)','Count positive votes among five trees. The output describes a majority decision, not three independent positive outcomes.'),
22:('initial=1\nupdates=[2,-1]\nrate=V/10\nprint(round(initial+rate*sum(updates),2))','A toy additive ensemble combines the initial prediction and shrunken updates. This illustrates update strength, not a full gradient-boosting training algorithm.'),
23:('train_groups={1,2}\nvalidation_groups={V,3}\nprint(sorted(train_groups & validation_groups))','The intersection exposes shared entities. With V=2 there is leakage for unseen-group evaluation; with V=3 the group sets are disjoint.'),
24:('candidates=V\nfolds=3\nprint(candidates*folds+1)','Every candidate is fitted once per fold, plus one final refit when refit=True. Do not count the refit as another validation score.'),
25:('from sklearn.metrics import mean_absolute_error\ny=[0,0]\np=[1,3]\nprint(round(mean_absolute_error(y,p,sample_weight=[V,1]),3))','Weighted MAE is the weighted error sum divided by the sum of weights: (V+3)/(V+1).'),
26:('prob=[0.2,0.5,0.8]\nthreshold=V/10\nprint([int(p>=threshold) for p in prob])','Apply the stated cutoff to each score. Thresholding changes decisions without retraining the probability model.'),
27:('prob=[0.1,0.9]\ny=[0,1]\nprint(round(sum((p-t)**2 for p,t in zip(prob,y))/2,3))','The binary Brier loss averages squared probability errors: calculate both from the supplied probabilities. This does not alone establish full calibration.'),
28:('from sklearn.feature_extraction.text import CountVectorizer\nv=CountVectorizer().fit(["red blue","blue green"])\nprint(v.transform(["red unseen"]*V).shape)','Vocabulary has three learned words; unseen is ignored. Each of V documents produces three feature columns.'),
29:('labels=[0,0,1,-1]\nprint(len(set(labels)-{-1}),labels.count(-1))','Count distinct non-noise IDs and noise examples separately. Noise label -1 is not an ordinary cluster for this interpretation.'),
30:('import numpy as np\nsupport=np.array([True,False,True,False])\nprint(np.arange(8).reshape(2,4)[:,support].shape)','Count True entries in the mask to find the retained feature width for two samples. Selection retains original columns rather than constructing PCA components.'),
31:('actual=[[1,0],[1,1]]\npredicted=[[1,1],[1,1]]\nprint(sum(a==b for a,b in zip(actual,predicted))/len(actual))','Subset accuracy requires the entire label vector to match. Count examples whose entire label vectors match, then divide by sample count.'),
32:('original_score=0.9\nshuffled_score=0.V\nprint(round(original_score-shuffled_score,2))','Permutation importance is a decrease in the chosen higher-is-better score, not the estimator’s impurity importance.'),
33:('errors=[1,2,3,V]\nprint(len(errors),round(sum(errors)/len(errors),2))','A report should distinguish the sample count and mean error. These fixed errors do not by themselves define a confidence or prediction interval.'),
34:('import numpy as np\nbefore=np.array([1.,2.])\nafter=np.array([1.,2.+1e-10])\nprint(np.allclose(before,after))','Compare the numerical difference with the comparison tolerance; a larger change should fail. A round-trip check compares behavior, not file size.'),
35:('required=["hours","distance"]\nreceived=["hours"] if V==2 else ["hours","distance"]\nprint(sorted(set(required)-set(received)))','The set difference lists missing required names. A correct number of columns alone does not establish the right schema.'),
36:('cv_errors={"baseline":V+3,"candidate":V}\nwinner=min(cv_errors,key=cv_errors.get)\nprint(winner)','Choose the smallest development error, then evaluate the frozen winner on a reserved final test.'),
37:('features=["age","future_outcome","distance"]\nprint([name for name in features if name!="future_outcome"])','An outcome-revealing feature must be removed on semantic grounds even if its validation score looks impressive.'),
38:('scores=[2,2,V,2]\nprint(all(score>=2 for score in scores))','The stated rubric requires every criterion to meet the threshold, rather than merely a good overall average.'),
39:('layers=(V,4)\nprint(len(layers),sum(layers))','An MLP hidden_layer_sizes tuple gives two hidden layers with V and four units. The sum is a unit count, not a learned-parameter count.'),
40:('labels=[1,-1,1,-1]\nprint(labels.count(-1))','IsolationForest uses -1 for flagged outliers and 1 for ordinary examples. A flag still needs investigation.'),
41:('import numpy as np\nx=np.array([[0,V]])\nprint(np.expm1(np.log1p(x)).round(2).tolist())','The supplied stateless forward and inverse maps preserve these valid inputs, including their row and feature structure.'),
42:('n=V*4\nbatch_size=4\nprint(len(list(range(0,n,batch_size))))','The loop starts once per four-row batch. Incremental state must be updated using a supported partial_fit method.'),
43:('outer=V\ninner=3\ncandidates=2\nprint(outer*(inner*candidates+1))','Each outer round runs six inner candidate fits and one refit. Nested evaluation costs outer times seven fits in this configuration.'),
44:('import pandas as pd\ns=pd.Series([10,20,30,40])\nprint(s.shift(1).rolling(2).mean().dropna().tolist())','Shift excludes the current target, then a two-observation rolling window averages earlier values; compute each window from the supplied series.'),
45:('learning_rates=[0.1,0.05]\nrounds=[20,40]\nprint([round(a*b,2) for a,b in zip(learning_rates,rounds)])','Compute the toy rate-times-round products. Equal products would still not make two learned boosting models equivalent. Training behavior still needs evaluation.'),
46:('counts={"negative":90,"positive":10}\nprint(counts["positive"]/sum(counts.values()))','Compute the validation prevalence from the supplied counts; it remains unchanged when only training folds are resampled. Do not report balanced evaluation as the natural population.'),
47:('status=[200,200,422,500]\nprint(sum(s>=400 for s in status),len(status))','Count statuses at least 400 among the four requests. Request reliability is not predictive accuracy, which requires target outcomes.')}
# Four concrete repair scenarios per module; no shared filler questions.
DEBUG={
1:[('X has 30 rows but y has 29. What needs repair?','Align one target to each input row without inventing an extra label.','Silently drop any prediction.'),('The baseline uses final-test labels to find the majority class. Repair it.','Fit the baseline using training labels only.','Keep it because it is a simple rule.'),('predict receives a one-dimensional feature vector for one sample. Repair it.','Supply one row with the expected feature width, such as [[a,b]].','Reshape every value into a new independent sample.'),('Probability columns are labeled from an assumed order. Repair it.','Read the fitted classes_ attribute before assigning names.','Assume positive always comes first.')],
2:[('The target was included in df.drop(columns=[]). What is wrong?','Explicitly remove the target and any unavailable outcome features from X.','Only rename the target column.'),('A feature is selected with df["x"] but an estimator expects a 2D table. Repair it.','Select df[["x"]] to preserve the feature dimension.','Transpose y repeatedly until no error occurs.'),('A plot of a subgroup omits its sample count. Improve the report.','State the sample count, units, missingness and selection limits.','Describe the pattern as a universal causal effect.'),('Rows are removed from X but not y. Repair it.','Apply the same row mask to both inputs and targets.','Sort y independently by numerical value.')],
3:[('A scaler is fitted on all rows before cross-validation. Repair it.','Put the scaler inside the evaluated pipeline.','Keep the pre-scaling because it has no labels.'),('The final-test score chooses the regularization setting. Repair it.','Choose settings using development validation or CV only.','Choose the highest final-test score and call it unbiased.'),('A fresh scaler is fitted on each test batch. Repair it.','Apply the training-fitted scaler unchanged to the test batch.','Normalize the test labels instead.'),('Cross-validation fits one classifier once, then scores several slices. Repair it.','Fit a fresh full workflow in each training fold.','Reuse the fitted model because every row is eventually validation.')],
4:[('A multiclass report uses the default binary F1 setting. Repair it.','Choose and report a suitable multiclass averaging rule or per-class report.','Relabel every mistake as positive.'),('R²=0.8 is called 80% exact prediction accuracy. Repair the interpretation.','Explain the squared-error reference comparison and report error units.','Increase R² by multiplying all predictions by 100.'),('Recall is computed as TP/(TP+FP). Repair it.','Recall uses TP/(TP+FN); the original expression is precision.','Keep it because both metrics use true positives.'),('RMSE on log targets is labeled as dollars. Repair it.','Inverse-transform predictions and evaluate in original target units.','Append a currency symbol to the log error.')],
5:[('One-hot feature width changes when future categories appear. Repair it.','Reuse the training-fitted encoder and define an unknown-category policy.','Refit the encoder for each request.'),('A target encoder sees each row’s target directly during training representation. Repair it.','Use leakage-aware cross-fitting inside model-selection folds.','Hide the target column after encoding and assume the leak vanished.'),('Pandas output is requested from sparse one-hot output and fails. Repair it.','Choose a compatible dense configuration when memory permits or keep sparse output.','Convert every zero to a missing value.'),('A target wrapper’s prediction is inverse-transformed twice. Repair it.','Use its already original-scale predict output once.','Apply a third inverse transform to cancel the second.')],
6:[('The neighbor model compares kilometres and large currency values without scale review. Repair it.','Evaluate a training-fitted scaling pipeline and justify the distance representation.','Always increase the number of neighbors until training score is perfect.'),('A deep tree’s training score is used as its generalization result. Repair it.','Evaluate on suitable held-out folds and control complexity if justified.','Call the training score final accuracy.'),('A native categorical booster receives category names as arbitrary numeric codes without declaring them categorical. Repair it.','Use supported categorical dtypes or an explicit categorical mask and inspect recognition.','Assume all integers are ordered categories automatically.'),('Early stopping watches the final test set. Repair it.','Use an internal or separate development validation partition within training boundaries.','Rename the final test to eval_set and keep using it.')],
7:[('The same patient appears in both row-shuffled partitions for unseen-patient deployment. Repair it.','Use a group-disjoint split matching the deployment.','Only stratify by class and ignore identity.'),('A search reports best_score_ as an unbiased final estimate. Repair it.','Evaluate the frozen search result on an untouched test or evaluate the selection procedure with outer CV.','Report only the winning fold.'),('A probability model is calibrated on the reserved final test. Repair it.','Learn calibration using development-only partitions.','Use the final-test labels because calibration is not training.'),('A low threshold is chosen after repeatedly inspecting final-test recall. Repair it.','Choose the threshold using a stated objective and development predictions.','Keep the threshold but delete its decision log.')],
8:[('The text vocabulary is fitted on all documents before splitting. Repair it.','Fit the vectorizer inside each training pipeline.','Keep it because text preprocessing has no numeric target.'),('Cluster IDs are scored as if cluster 0 must equal class 0. Repair it.','Use clustering-appropriate comparison or permutation-invariant alignment and state its limits.','Sort the numeric labels and assume they now match.'),('PCA is fitted on all data before validating a classifier. Repair it.','Fit PCA inside the evaluated predictor pipeline.','Keep it because PCA ignores y.'),('Subset accuracy is called average per-label accuracy. Repair it.','Explain that subset accuracy requires the whole label set to match.','Replace every missing label with the most frequent label.')],
9:[('Importance is reported as a causal effect. Repair it.','Describe model dependence under the inspection method and state causal limitations.','Declare the highest importance the strongest intervention.'),('An unnamed array reverses the trained feature order but still returns predictions. Repair it.','Validate names, order and units before prediction.','Accept the output because no error was raised.'),('Only the classifier is saved from a preprocessing pipeline. Repair it.','Persist the complete fitted workflow and its environment/input contract.','Fit a new scaler independently at serving time.'),('Bootstrap MAE endpoints are called bounds for each future target. Repair it.','Call them conditional uncertainty for the metric under the stated resampling assumptions.','Treat every interval as an individual prediction interval.')],
10:[('A capstone chooses settings by final-test score. Repair it.','Move selection to development data and honestly document the consumed test.','Hide the earlier test results and reuse it as untouched.'),('A project lacks data access instructions. Repair it.','Record provenance, permitted access and exact dataset/version details.','Upload restricted raw data without checking terms.'),('A report omits an underperforming baseline comparison. Repair it.','Report the baseline and explain the negative result.','Keep only the best-looking model table.'),('A self-review marks all criteria strong without evidence. Repair it.','Attach reproducible evidence and score each criterion honestly.','Use a high average to conceal a missing criterion.')],
11:[('SMOTE runs before folds are created. Repair it.','Use a sampling-aware pipeline within training folds.','Balance the final test too.'),('A rolling feature includes the current target. Repair it.','Shift according to the forecast horizon before computing the window.','Shuffle timestamps to hide the timing.'),('Stacking meta-features use in-sample base predictions. Repair it.','Generate out-of-fold base predictions for meta-training.','Increase meta-model complexity to absorb the leak.'),('Input drift is reported as measured accuracy loss without outcomes. Repair it.','Report drift as an input signal and evaluate predictive quality when representative outcomes arrive.','Invent accuracy from the drift p-value.')]
}
ALTERNATE={12:('[0.2,0.8]','[0.7,0.3]'),21:('[0,1,1,1,0]','[0,0,1,0,0]'),27:('[0.1,0.9]','[0.4,0.6]'),29:('[0,0,1,-1]','[0,1,2,-1]'),30:('[True,False,True,False]','[True,True,True,False]'),31:('predicted=[[1,1],[1,1]]','predicted=[[1,0],[1,1]]'),34:('[1.,2.+1e-10]','[1.,2.1]'),37:('["age","future_outcome","distance"]','["hours","future_outcome"]'),40:('[1,-1,1,-1]','[1,1,1,-1]'),44:('[10,20,30,40]','[5,10,15,20]'),45:('[0.1,0.05]','[0.1,0.025]'),46:('90,"positive":10','80,"positive":20'),47:('[200,200,422,500]','[200,200,200,422]')}
def output_questions(chapter):
 template,explanation=CASES[chapter]
 questions=[]
 for variant in (2,3):
    code=re.sub(r'\bV\b', str(variant), template)
    if variant==3 and chapter in ALTERNATE:
        old,new=ALTERNATE[chapter]
        code=code.replace(old,new)
    # Every snippet is authored locally; execute it to verify its expected output.
    capture=io.StringIO()
    with contextlib.redirect_stdout(capture):exec(code,{})
    expected=capture.getvalue().strip()
    def alter_first_number(delta):
        def change(match):
            value=float(match.group())+delta
            return str(int(value)) if value.is_integer() and '.' not in match.group() else str(round(value,3))
        return re.sub(r'-?\d+(?:\.\d+)?', change, expected, count=1)
    if re.search(r'\d',expected):
        distractors=[alter_first_number(1),alter_first_number(-1),alter_first_number(2)]
    elif expected in ['True','False']:
        distractors=['False' if expected=='True' else 'True','None','[]']
    else:
        distractors=['baseline','candidate','None','True','False']
    alternatives=[expected]+[value for value in distractors if value!=expected][:3]
    questions.append(dict(id=f'{chapter}-transfer-{variant}',chapter=chapter,type='Predict the output',prompt='Reason from these new inputs: what does this short snippet print?',code=code,options=list(dict.fromkeys(alternatives)),correct=0,explanation=explanation))
 return questions

def debugging_questions(module,start):
 return [dict(id=f'm{module}-repair-{i}',chapter=([46,44,43,47][i] if module==11 else start),type='Debugging',prompt=prompt,options=[answer,wrong],correct=0,explanation=answer) for i,(prompt,answer,wrong) in enumerate(DEBUG[module])]
